import{_ as t,o as a,c as s,ab as r}from"./chunks/framework.DfnUYNhO.js";const k=JSON.parse('{"title":"当前传输方式与平台限制","description":"","frontmatter":{"title":"当前传输方式与平台限制","docId":"developer.transports","translationKey":"developer.transports","locale":"zh","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"e061718f08cd5971f353da7709d4ea21feae8b6e2962b55de82e86544ca28209","order":200},"headers":[],"relativePath":"zh/developer/transports.md","filePath":"zh/developer/transports.md","lastUpdated":1795474668000}'),o={name:"zh/developer/transports.md"};function i(d,e,n,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">当前传输方式与平台限制 <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;当前传输方式与平台限制 {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择目标构建和平台上实际存在的传输方式。先阅读 <a href="./control-api.html">Control API</a> 和<a href="./collaboration.html">协作</a>。传输负责承载序列化操作，不能引入第二个核心，也不能自行授予权限。</p><h2 id="choose-the-boundary" tabindex="-1">选择边界 <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;选择边界 {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>当前实现</th><th>重要限制</th></tr></thead><tbody><tr><td>桌面 WebView</td><td>Wry IPC 与共享控制客户端</td><td>GUI/线程生命周期归桌面端所有</td></tr><tr><td>本地 CLI</td><td>Unix socket 或 Windows 命名管道；显式 stdio 主机</td><td>同一应用目录与所有者</td></tr><tr><td>本地浏览器</td><td>原生回环适配器加 <code>browser-transport.ts</code></td><td>已配对的原生主机，不是公开远程服务器</td></tr><tr><td>已认证的 HTTPS/WSS 网关</td><td>带 TLS、hello、授权与特性门控的 SDK/浏览器传输</td><td>远程命令需要显式授权</td></tr><tr><td>可安装的远程控制插件</td><td>基于 WSS 中继、使用 <code>remote.controller.ticket</code> 的 <code>tiktools.remote-control</code></td><td>由插件拥有；主机不编译任何远程代码</td></tr></tbody></table><p>TypeScript 传输接口位于 <code>src/web/shared/api/control-transport.ts</code>。远程控制是可安装插件，不属于主机二进制文件：每条命令都要经过 <code>HostCallPolicy</code>（<code>remote.command.dispatch</code>、<code>remote.pair.list</code>、<code>remote.grant.list</code>、<code>remote.grant.revoke</code>、<code>remote.controller.ticket</code>）。此构建不包含原生 peer/RTC 传输，也没有 Cloud Teams 主机链接。</p><h2 id="inspect-the-selected-route" tabindex="-1">检查所选路由 <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;检查所选路由 {#inspect-the-selected-route}&quot;">​</a></h2><p>在配对或显示控制操作前，先查询已连接主机支持的方法与能力：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>配对与授权由插件负责：控制器票据短期有效且只能使用一次，<code>remote.grant.list</code> / <code>remote.grant.revoke</code> 是权威视图。中继连接只证明传输可用，绝不代表拥有 RPC 权限。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>本地 IPC 与桌面传输已是稳定路径。远程控制通过可安装插件和已认证中继工作，不是第二个主机运行时。登录码会以五分钟有效期中继给已连接设备；未配置账户时回退到 OAuth。Android 本地 IPC 可配合插桩版 <code>mobile</code> 工具（<code>info</code> / <code>exec</code> / <code>tty</code>）使用；桌面原生插件与 WebView 在该平台仍不可用。</p><h2 id="recovery" tabindex="-1">恢复 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复 {#recovery}&quot;">​</a></h2><p>对于已接受的操作，断连可能意味着结果不确定。重连时必须作废旧投影、重新协商身份，并恢复或快照有界流。切勿降级证书校验，也不要在远程失败后静默回退到本地所有者。过期的控制器票据和已撤销的授权必须 fail closed。</p><h2 id="operational-details" tabindex="-1">运维细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运维细节 {#operational-details}&quot;">​</a></h2><p>授权应遵循最小权限并设时限，每次重连后都要重新检查。分别排查身份、票据过期、授权范围、中继可达性与帧大小。超大帧会在帧校验处失败，不会变成部分 RPC。在真实双设备验收前，先用 fixture 测试变更或撤销的会话。</p>`,16)])])}const u=t(o,[["render",i]]);export{k as __pageData,u as default};
